drop policy if exists dd_work_orders_provider_update on public.dd_work_orders;
create policy dd_work_orders_provider_update on public.dd_work_orders for update to authenticated using (exists (select 1 from public.dd_jobs j join public.dd_job_assignments a on a.job_id = j.id where j.work_order_id = dd_work_orders.id and a.provider_id = private.dd_current_provider_id() and a.assignment_status = 'ACCEPTED')) with check (exists (select 1 from public.dd_jobs j join public.dd_job_assignments a on a.job_id = j.id where j.work_order_id = dd_work_orders.id and a.provider_id = private.dd_current_provider_id() and a.assignment_status = 'ACCEPTED'));
